import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class CheerfulChargeTest {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static AttackDefinition attack(){return LegacyPokemonProgramRepairTest.PROFILES.get("swsh12-5a_en_001").attacks().getFirst();}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static void check(boolean b,String why){GeneratedRuleBatch8Test.check(b,why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static ServerMatch game(UUID second){
        var defs=new CardDatabase(List.of(StadiumActivationTest.definition("basic",CardCategory.POKEMON,TrainerCategory.NONE,true),
            StadiumActivationTest.definition("grass",CardCategory.ENERGY,TrainerCategory.NONE,false),
            StadiumActivationTest.definition("special",CardCategory.ENERGY,TrainerCategory.NONE,false)));
        // Set basic Energy explicitly; a Special Energy that supplies Grass is still ineligible in the deck.
        var entries=new ArrayList<CardDefinition>();for(var d:defs.all())entries.add(new CardDefinition(d.id(),d.nameZh(),d.category(),d.trainerCategory(),"I",Set.of("international"),d.basicPokemon(),d.id().equals("grass"),60,Map.of(),EffectSupport.SUPPORTED,null));
        var profile=new PokemonProfile(500,0,null,null,0,null,0,1,List.of(attack(),GeneratedRuleBatch8Test.hit(300,false)),List.of(),EnergyType.GRASS);
        var combat=new CombatCatalog(Map.of("basic",profile),Map.of("grass",EnergyType.GRASS),Map.of(),Map.of("special",EnergyProfile.fixed(EnergyType.GRASS,2)));
        for(int seed=0;seed<200;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,i<36?"basic":i<54?"grass":"special"));decks.add(cards);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(entries),combat,new ServerRandom(seed));m.callCoin(A,CoinSide.HEADS);UUID winner=m.publicCoinResult()==CoinSide.HEADS?A:B;m.chooseWhoGoesFirst(winner,winner.equals(other(second)));if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);for(UUID p:List.of(A,B))m.drawCardsByEffect(other(second),p,18);return m;}throw new AssertionError("No Cheerful Charge fixture");
    }
    static void select(ServerMatch m,UUID p,List<CardInstance> cards){NonPokemonBatch120Test.select(m,p,cards);}
    public static void main(String[] args){timing();choices();ai();System.out.println("CheerfulChargeTest passed: both seats, only second player's first turn, public hosts fixed before private search, 0..2 distinct Bench hosts, same-type Basic Energy allowed, one per selected host, stale/foreign/Active rejection and eight complete four-tier AI matches");}
    static void timing(){for(UUID p:List.of(A,B)){var m=game(p);reject(()->m.attack(other(p),attack().id()));m.endTurn(other(p));check(m.activeAttacks(p).stream().anyMatch(a->a.id().equals(attack().id())),"Second player's first turn disallowed");m.endTurn(p);reject(()->m.attack(other(p),attack().id()));m.endTurn(other(p));reject(()->m.attack(p,attack().id()));}}
    static void choices(){for(UUID p:List.of(A,B))for(int count=0;count<=2;count++){var m=game(p);m.endTurn(other(p));NonPokemonBatch120Test.fill(m,p,3);var targets=NonPokemonBatch120Test.hosts(m,p,count);var energies=m.privateView(p).hand().stream().filter(c->c.definitionId().equals("grass")).limit(2).toList();check(energies.size()==2,"Missing same-type fixture Energy");PairedTrainerPlayTest.zone(m,p,"hand").removeAll(energies);PairedTrainerPlayTest.zone(m,p,"deck").addAll(energies);int turn=m.turnNumber();m.attack(p,attack().id());var q=m.effectCardPrompt(p);check(q.minimum()==0&&q.maximum()==2&&q.candidates().size()==3&&q.candidates().stream().allMatch(c->c.definitionId().equals("basic")),"Private deck exposed before selecting public hosts");reject(()->select(m,p,NonPokemonBatch120Test.hosts(m,p,3)));reject(()->select(m,p,List.of(EventTargetBindingTest.field(m).topCard(p,m.activePokemonView(p).pokemonId()))));reject(()->m.submitEffectCards(other(p),q.resolutionId(),q.step(),List.of()));select(m,p,targets);reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of()));if(count>0){var search=m.effectCardPrompt(p);check(search.maximum()==count&&search.candidates().containsAll(energies)&&search.candidates().stream().allMatch(c->c.definitionId().equals("grass")),"Search limits or Special Energy filtering wrong");select(m,p,energies.subList(0,count));var dist=m.effectAttachmentPrompt(p);check(dist.targets().size()==count,"Unchosen host available after search");if(count==2){UUID first=PokemonIdentityTestSupport.logical(m,p,targets.getFirst().instanceId());for(var energy:energies)m.assignEffectEnergyDistribution(p,dist.resolutionId(),dist.step(),energy.instanceId(),first);reject(()->m.confirmEffectEnergyDistribution(p,dist.resolutionId(),dist.step()));}NonPokemonBatch120Test.assign(m,p,energies.subList(0,count),targets);}check(m.currentPlayer().equals(other(p))&&m.turnNumber()==turn+1&&m.benchPokemonView(p).stream().mapToInt(v->v.attachedEnergyIds().size()).sum()==count&&!m.hasPendingEffectChoice(),"Charge stalled, ended twice or attached to wrong hosts");}}
    static void ai(){for(UUID p:List.of(A,B))for(var level:AiDifficulty.values()){var m=game(p);m.endTurn(other(p));NonPokemonBatch120Test.fill(m,p,3);m.attack(p,attack().id());var s=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(s,level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"AI could not finish Charge: "+level);}}
}
